-- Reforma tributária (LC 214/2025) parametrizada, e não mais fixa no código.
--
-- 1. Tabela oficial de classificação tributária do IBS/CBS (cClassTrib e CST),
--    copiada do Portal da Conformidade Fácil (dfe-portal.svrs.rs.gov.br/Cff,
--    Informe Técnico 2025.002), publicação de 01/10/2026. É referência nacional,
--    igual para todas as empresas; nenhuma empresa grava nela. Atualizar = nova
--    migração com a nova publicação.
-- 2. Alíquotas por ano e por empresa. A lei fixa o IBS de 2026 (0,1% UF) e de
--    2027-2028 (0,05% UF + 0,05% município) e a CBS de 2026 (0,9%); esses valores
--    vêm do domínio quando a empresa não cadastrou nada. A CBS de 2027 em diante
--    é a alíquota de referência fixada pela União menos 0,1 ponto (art. 347): sem
--    cadastro, a nota de 2027 é recusada antes da SEFAZ.
-- 3. cClassTrib padrão por CFOP, por empresa (bonificação, transferência,
--    exportação…). O CFOP é global; o vínculo com a classificação é da empresa.
-- 4. A linha da NF-e de saída aceita cClassTrib próprio (sobrescrita) e guarda o
--    retrato do grupo IBS/CBS que foi transmitido.

CREATE TABLE ibscbs_classificacoes (
    cclass_trib        CHAR(6)      PRIMARY KEY CHECK (cclass_trib ~ '^[0-9]{6}$'),
    cst                CHAR(3)      NOT NULL CHECK (cst = LEFT(cclass_trib, 3)),
    cst_descricao      TEXT         NOT NULL,
    descricao          TEXT         NOT NULL,
    exige_tributacao   BOOLEAN      NOT NULL,
    reducao_aliquota   BOOLEAN      NOT NULL,
    diferimento        BOOLEAN      NOT NULL,
    perc_reducao_ibs   NUMERIC(7,4) NOT NULL CHECK (perc_reducao_ibs BETWEEN 0 AND 100),
    perc_reducao_cbs   NUMERIC(7,4) NOT NULL CHECK (perc_reducao_cbs BETWEEN 0 AND 100),
    tipo_aliquota      SMALLINT     NOT NULL,
    tributacao_regular BOOLEAN      NOT NULL,
    aceita_nfe         BOOLEAN      NOT NULL,
    vigencia_inicio    DATE         NOT NULL,
    vigencia_fim       DATE,
    url_legislacao     TEXT,
    versao_tabela      TEXT         NOT NULL DEFAULT 'IT 2025.002 — Conformidade Fácil, publicação 2026-10-01'
);
CREATE INDEX idx_ibscbs_classificacoes_cst ON ibscbs_classificacoes(cst);

INSERT INTO ibscbs_classificacoes
    (cclass_trib, cst, cst_descricao, descricao, exige_tributacao, reducao_aliquota, diferimento,
     perc_reducao_ibs, perc_reducao_cbs, tipo_aliquota, tributacao_regular, aceita_nfe,
     vigencia_inicio, vigencia_fim, url_legislacao)
