    ('800001', '800', 'Transferência de crédito', 'Fusão, cisão ou incorporação, observado o art. 55 da Lei Complementar nº 214, de 2025.', FALSE, FALSE, FALSE, 0.0000, 0.0000, 3, FALSE, TRUE, '2025-05-05', NULL, 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art55'),
    ('800002', '800', 'Transferência de crédito', 'Transferência de crédito do associado, inclusive as cooperativas singulares, para cooperativa de que participa das operações antecedentes às operações em que fornece bens e serviços e os créditos presumidos, observado o art. 272 da Lei Complementar nº 214, de 2025.', FALSE, FALSE, FALSE, 0.0000, 0.0000, 3, FALSE, TRUE, '2025-05-05', NULL, 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art272'),
    ('810001', '810', 'Ajuste de IBS na ZFM', 'Crédito presumido sobre o valor apurado nos fornecimentos a partir da Zona Franca de Manaus, observado o art. 450 da Lei Complementar nº 214, de 2025.', FALSE, FALSE, FALSE, 0.0000, 0.0000, 3, FALSE, TRUE, '2025-05-05', NULL, 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art450'),
    ('811001', '811', 'Ajustes', 'Anulação de crédito proporcional ao valor das operações imunes e isentas, observado o art. 51 da Lei Complementar nº 214, de 2025.', FALSE, FALSE, FALSE, 0.0000, 0.0000, 3, FALSE, TRUE, '2025-09-30', NULL, 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art51
