    ('820004', '820', 'Tributação em documento específico', 'Documento com informações de prestação de serviços de consursos de prognósticos, mas com tributação realizada por outro meio, observado o art. 248 da Lei Complementar nº 214, de 2025.', FALSE, FALSE, FALSE, 0.0000, 0.0000, 3, FALSE, FALSE, '2025-05-05', NULL, 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art248'),
    ('820005', '820', 'Tributação em documento específico', 'Documento com informações de alienação de bens imóveis, mas com tributação realizada por outro meio,, observado o art. 254 da Lei Complementar nº 214, de 2025.', FALSE, FALSE, FALSE, 0.0000, 0.0000, 3, FALSE, FALSE, '2025-05-05', NULL, 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art254'),
