    ('830001', '830', 'Exclusão da Base de Cálculo', 'Documento com  exclusão da base de cálculo da CBS e do IBS refrente à energia elétrica fornecida pela distribuidora à unidade consumidora, conforme  Art 28, parágrafos 3° e 4°.', TRUE, FALSE, FALSE, 0.0000, 0.0000, 2, FALSE, TRUE, '2025-05-05', NULL, 'https://www.planalto.gov.br/ccivil_03/leis/lcp/lcp214.htm#art28');

CREATE TABLE ibscbs_aliquotas (
    enterprise_id BIGINT       NOT NULL REFERENCES enterprise(id) ON DELETE CASCADE,
    ano           INT          NOT NULL CHECK (ano BETWEEN 2026 AND 2100),
    ibs_uf        NUMERIC(7,4) NOT NULL CHECK (ibs_uf >= 0 AND ibs_uf < 100),
    ibs_mun       NUMERIC(7,4) NOT NULL CHECK (ibs_mun >= 0 AND ibs_mun < 100),
    cbs           NUMERIC(7,4) NOT NULL CHECK (cbs >= 0 AND cbs < 100),
    fundamento    TEXT         NOT NULL CHECK (length(trim(fundamento)) > 0),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_by    UUID         NOT NULL REFERENCES users(id),
    PRIMARY KEY (enterprise_id, ano)
);

CREATE TABLE ibscbs_cfop_classificacoes (
    enterprise_id BIGINT      NOT NULL REFERENCES enterprise(id) ON DELETE CASCADE,
    cfop          VARCHAR(4)  NOT NULL CHECK (cfop ~ '^[0-9]{4}$'),
    cclass_trib   CHAR(6)     NOT NULL REFERENCES ibscbs_classificacoes(cclass_trib),
    observacao    TEXT,
    updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_by    UUID        NOT NULL REFERENCES users(id),
    PRIMARY KEY (enterprise_id, cfop)
);

ALTER TABLE fiscal_exit_items
    ADD COLUMN ibscbs_cclass_trib  CHAR(6) REFERENCES ibscbs_classificacoes(cclass_trib),
    -- Retrato do grupo IBS/CBS transmitido (gravado na autorização).
    ADD COLUMN ibscbs_cst_enviado        CHAR(3),
    ADD COLUMN ibscbs_cclass_enviado     CHAR(6),
    ADD COLUMN ibscbs_origem             VARCHAR(20),
    ADD COLUMN ibscbs_base               NUMERIC(15,2),
    ADD COLUMN ibs_uf_aliquota_efetiva   NUMERIC(7,4),
    ADD COLUMN ibs_uf_valor              NUMERIC(15,2),
    ADD COLUMN ibs_mun_aliquota_efetiva  NUMERIC(7,4),
    ADD COLUMN ibs_mun_valor             NUMERIC(15,2),
    ADD COLUMN cbs_aliquota_efetiva      NUMERIC(7,4),
    ADD COLUMN cbs_valor                 NUMERIC(15,2);

ALTER TABLE fiscal_exits
    ADD COLUMN valor_ibs NUMERIC(15,2),
    ADD COLUMN valor_cbs NUMERIC(15,2);
